<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/includes/bootstrap.php'; require_admin();
$db=database_connection(); $error=''; $notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!verify_csrf_token($_POST['csrf_token']??null)) $error='This page expired. Refresh and try again.';
 elseif(($_POST['action']??'')==='add'){
  $name=trim((string)($_POST['student_name']??''));$title=trim((string)($_POST['story_title']??''));$url=trim((string)($_POST['video_url']??''));$quote=trim((string)($_POST['quote']??''));
  if($name===''||text_length($name)>120||$title===''||text_length($title)>180||youtube_video_id($url)===''||text_length($quote)>500) $error='Add a student name, story title, valid YouTube link, and a quote under 500 characters.';
  else{$q=$db->prepare('INSERT INTO video_testimonials (student_name,story_title,video_url,quote) VALUES (:name,:title,:url,:quote)');$q->execute(['name'=>$name,'title'=>$title,'url'=>$url,'quote'=>$quote]);$notice='Video story added to the homepage.';}
 }elseif(($_POST['action']??'')==='remove'){$q=$db->prepare('UPDATE video_testimonials SET active=0 WHERE id=:id');$q->execute(['id'=>(int)($_POST['id']??0)]);$notice='Video story hidden from the homepage.';}
}
$videos=$db->query('SELECT id,student_name,story_title,video_url,active FROM video_testimonials ORDER BY id DESC')->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Video stories · You Aspirant admin</title><link rel="stylesheet" href="../styles.css"><link rel="stylesheet" href="admin.css"><link rel="stylesheet" href="../features.css"></head><body class="admin-body"><header class="dashboard-header"><a class="admin-brand" href="/admin"><span class="brand-mark"><span>Y</span></span><span><strong>you aspirant</strong><small>Student stories</small></span></a><a class="logout-button" href="/admin">Inbox ↗</a></header><?php require __DIR__.'/_nav.php';?><main class="dashboard-main"><div class="dashboard-title"><div><p class="admin-eyebrow">Share approved experiences</p><h1>Video stories</h1></div></div><?php if($notice):?><p class="admin-notice"><?=escape_html($notice)?></p><?php endif;?><?php if($error):?><p class="admin-error"><?=escape_html($error)?></p><?php endif;?><div class="admin-content-grid"><form class="feature-panel feature-form" method="post"><h2>Add video testimonial</h2><input type="hidden" name="csrf_token" value="<?=escape_html(csrf_token())?>"><input type="hidden" name="action" value="add"><label>Student name<input name="student_name" maxlength="120" required></label><label>Story title<input name="story_title" maxlength="180" required></label><label>YouTube video URL<input name="video_url" type="url" maxlength="500" placeholder="https://youtu.be/..." required></label><label>Student quote<textarea name="quote" maxlength="500" rows="4"></textarea></label><button class="button button-dark" type="submit">Add story ↗</button><p class="feature-muted">Only add videos you have permission to publish.</p></form><section class="feature-panel"><h2>Published videos</h2><div class="admin-list"><?php foreach($videos as $video):?><article><div><strong><?=escape_html($video['story_title'])?></strong><small><?=escape_html($video['student_name'])?> · <?=$video['active']?'Shown':'Hidden'?></small></div><?php if($video['active']):?><form method="post"><input type="hidden" name="csrf_token" value="<?=escape_html(csrf_token())?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="id" value="<?=(int)$video['id']?>"><button class="row-action" type="submit">Hide</button></form><?php endif;?></article><?php endforeach;?></div></section></div></main></body></html>
